mapper.select:
SELECT A.BOOKSET_ID, A.SUBJECT_NO, A.SUBJECT_NAME, A.FSUBJECT_ID, A.BAL_FLAG, A.SUBJECT_TYPE, A.SUBJECT_LEVEL, A.ACC_QUA_FLAG, A.ACC_INT_FLAG, A.OVERDRAWN_FLAG, A.GEN_DETSUB_FLAG, A.BASE_SUBJECT_NATURE, A.INV_AIM, A.SEC_MANAGE_ACCT_ID, A.SUBJECT_INTERNAL_CODE, A.SUBJECT_HAND_FEL_CODE, A.CCY FROM BOK_SUBJECT A INNER JOIN BOK_BOOKSET B ON A.BOOKSET_ID = B.BOOKSET_ID_TMPL WHERE B.BOOKSET_ID = #{booksetId} AND A.CCY = #{ccy} /** 查询底层科目，且科目配置项不为空**/ AND A.IS_BOTTOM = 'Y'
AND A.SUBJECT_INTERNAL_CODE IN
#{item}

SELECT A.BOK_DETAIL_ID AS bokDetailId, E.TYPE_18 as secType, /** 证券类型**/ E.TYPE_2 as secDetailType, /**证券细分类 **/ nvl(B.TRADE_MARKET,C.TRADE_MARKET) as tradeMarket, /** 交易市场 **/ B.ISSUE_TYPE as issueType, /** 发行方式 **/ CASE WHEN A.BUSI_DETAIL_TYPE = #{finprodTypeCk} THEN B.ISSUER /** 存款类资产对应市场机构 **/ ELSE C.COUNTER_ID END as counterId, /** 交易对手 **/ A.BUSI_DETAIL_TYPE as accountType, /** 账户类型 **/ NVL(B.REGIST_ORG, D.REGIST_ORG) as feeType, /**登记托管机构（费用类型）**/ E.TYPE_3 as taxFeeType /** 税务分类（税费类型） **/ FROM BOK_DETAIL_ID A LEFT JOIN FIN_PRODUCT B ON A.BUSI_ID = B.FINPROD_ID AND A.BUSI_DETAIL_TYPE = B.FINPROD_TYPE LEFT JOIN FIN_TRADE_PRODUCT C ON A.BUSI_ID = C.FINPROD_ID AND A.BUSI_DETAIL_TYPE = C.FINPROD_TYPE AND C.BRANCH = 0 LEFT JOIN FIN_TRADE_PRODUCT_ADD D ON D.FINPROD_ID = A.BUSI_ID AND D.BRANCH = 0 LEFT JOIN FIN_PRODUCT_TYPE E ON A.BUSI_ID = E.FINPROD_ID WHERE A.BOOKSET_ID = #{booksetId}
AND A.BOK_DETAIL_ID IN
#{item}
